import java.util.ArrayList;
import java.util.List;

public class HeaderFooterBodyContainersetTable_CTHdrFtrsetTblArrayFikaTest {

    @Test
    public void testSetTableInvokesSetTblArray() throws Exception {
        // Create a mock CTHdrFtr that will receive the setTblArray call
        CTHdrFtr mockHdrFtr = Mockito.mock(CTHdrFtr.class);

        // Create a real CTTbl object for the table
        CTTbl ctTbl = CTTbl.Factory.newInstance();

        // Create a real XWPFTable with the CTTbl
        XWPFTable table = Mockito.mock(XWPFTable.class);
        Mockito.when(table.getCTTbl()).thenReturn(ctTbl);

        // Create a mock headerFooter object that returns our mock CTHdrFtr
        Object mockHeaderFooter = Mockito.mock(Object.class, Mockito.withSettings()
                .extraInterfaces(org.apache.poi.xwpf.usermodel.IBody.class));

        // Use reflection to set up the headerFooter's behavior
        Mockito.when(((org.apache.poi.xwpf.usermodel.IBody) mockHeaderFooter)._getHdrFtr())
                .thenReturn(mockHdrFtr);

        // Create a real list for tables
        List<XWPFTable> tables = new ArrayList<>();
        tables.add(null); // Add a placeholder at position 0

        // Create the container under test
        HeaderFooterBodyContainer container = new HeaderFooterBodyContainer(mockHeaderFooter);

        // Use reflection to set the tables list on the headerFooter object
        java.lang.reflect.Field tablesField = mockHeaderFooter.getClass().getSuperclass()
                .getDeclaredField("tables");
        tablesField.setAccessible(true);
        tablesField.set(mockHeaderFooter, tables);

        // Invoke the entry point method
        container.setTable(0, table);

        // The call chain should have invoked: mockHdrFtr.setTblArray(0, ctTbl)
    }
}

