import org.junit.jupiter.api.Test;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTP;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTSdt;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTSdtContentBlock;

public class SDTBodyContainersetParagraph_XWPFParagraphgetCTPFikaTest {

    @Test
    public void test() throws Exception {
        XWPFDocument document = new XWPFDocument();
        CTSdt sdt = CTSdt.Factory.newInstance();
        CTSdtContentBlock content = sdt.addNewSdtContentBlock();
        content.addNewP();

        SDTBodyContainer container = createContainer(document, sdt, content);

        Field containerField = findField(SDTBodyContainer.class, "sdtContent");
        Object sdtContent = null;
        if (containerField != null) {
            containerField.setAccessible(true);
            sdtContent = containerField.get(container);
        }

        if (sdtContent == null) {
            sdtContent = createSdtContent(document, sdt, content);
            if (containerField != null) {
                containerField.setAccessible(true);
                try {
                    containerField.set(container, sdtContent);
                } catch (Throwable ignored) {
                }
            }
        }

        XWPFParagraph paragraph = prepareParagraph(content, document, sdtContent);
        container.setParagraph(paragraph, 0);
    }

    private SDTBodyContainer createContainer(XWPFDocument document, CTSdt sdt, CTSdtContentBlock content) throws Exception {
        Object sdtContent = createSdtContent(document, sdt, content);

        for (Constructor<?> ctor : SDTBodyContainer.class.getDeclaredConstructors()) {
            if (ctor.getParameterCount() == 1) {
                Class<?> paramType = ctor.getParameterTypes()[0];
                Object arg = sdtContent;
                if (arg == null || !paramType.isInstance(arg)) {
                    arg = createArgFor(paramType, document, sdt, content);
                }
                if (arg != null) {
                    ctor.setAccessible(true);
                    return (SDTBodyContainer) ctor.newInstance(arg);
                }
            }
        }

        for (Constructor<?> ctor : SDTBodyContainer.class.getDeclaredConstructors()) {
            Object[] args = new Object[ctor.getParameterCount()];
            try {
                ctor.setAccessible(true);
                SDTBodyContainer container = (SDTBodyContainer) ctor.newInstance(args);
                Field field = findField(SDTBodyContainer.class, "sdtContent");
                if (field != null && sdtContent != null) {
                    field.setAccessible(true);
                    try {
                        field.set(container, sdtContent);
                    } catch (Throwable ignored) {
                    }
                }
                return container;
            } catch (Throwable ignored) {
            }
        }

        throw new IllegalStateException("Unable to instantiate SDTBodyContainer");
    }

    private Object createSdtContent(XWPFDocument document, CTSdt sdt, CTSdtContentBlock content) {
        Object block = tryInstantiate("org.apache.poi.xwpf.usermodel.XWPFSDTContentBlock", content, sdt, document);
        if (block != null) {
            return block;
        }
        return tryInstantiate("org.apache.poi.xwpf.usermodel.XWPFSDT", content, sdt, document);
    }

    private Object createArgFor(Class<?> paramType, XWPFDocument document, CTSdt sdt, CTSdtContentBlock content) {
        if (paramType.isAssignableFrom(CTSdtContentBlock.class)) {
            return content;
        }
        if (paramType.isAssignableFrom(CTSdt.class)) {
            return sdt;
        }
        if (paramType.isAssignableFrom(XWPFDocument.class)) {
            return document;
        }

        try {
            Class<?> blockClass = Class.forName("org.apache.poi.xwpf.usermodel.XWPFSDTContentBlock");
            if (paramType.isAssignableFrom(blockClass)) {
                return tryInstantiate("org.apache.poi.xwpf.usermodel.XWPFSDTContentBlock", content, sdt, document);
            }
        } catch (Throwable ignored) {
