        CTTxbxContent ctTxbxContent = CTTxbxContent.Factory.newInstance();
        ctTextBox.setTxbxContent(ctTxbxContent);

        Class<?> pictureBoxClass = findPictureBoxClass();
        Object textbox = createPictureBox(pictureBoxClass, ctTextBox, paragraph, document);

        CTTxbxContent actualTxbxContent = getCTTxbxContent(pictureBoxClass, textbox, ctTxbxContent);
        if (actualTxbxContent.getPArray() == null || actualTxbxContent.getPArray().length == 0) {
            actualTxbxContent.addNewP();
        }

        ensureParagraphs(pictureBoxClass, textbox);

        TextBoxBodyContainer container = createTextBoxBodyContainer(pictureBoxClass, textbox);
        container.setParagraph(paragraph, 0);
    }

    private Class<?> findPictureBoxClass() throws Exception {
        Field field = findField(TextBoxBodyContainer.class, "textbox");
        if (field != null && isPictureBoxLike(field.getType())) {
            return field.getType();
        }

        for (Constructor<?> ctor : TextBoxBodyContainer.class.getDeclaredConstructors()) {
            for (Class<?> parameterType : ctor.getParameterTypes()) {
                if (isPictureBoxLike(parameterType)) {
                    return parameterType;
                }
