            return Class.forName("org.apache.poi.xwpf.usermodel.XWPFPictureBox");
        } catch (ClassNotFoundException e) {
            throw new IllegalStateException("Unable to locate XWPFPictureBox", e);
        }
    }

    private boolean isPictureBoxLike(Class<?> type) {
        if (type == null || type.isPrimitive() || type.isArray() || type.equals(Object.class)) {
            return false;
        }
        if (type.getName().contains("PictureBox")) {
            return true;
        }
        return findMethod(type, "getCTTxbxContent", new Class<?>[0]) != null;
    }

    private Object createPictureBox(Class<?> clazz, CTTextBox ctTextBox, XWPFParagraph paragraph,
            XWPFDocument document) throws Exception {
        Exception last = null;

        try {
            Constructor<?> ctor = clazz.getDeclaredConstructor(CTTextBox.class, XWPFParagraph.class);
            ctor.setAccessible(true);
            return ctor.newInstance(ctTextBox, paragraph);
        } catch (Exception e) {
            last = e;
        }

        try {
            Constructor<?> ctor = clazz.getDeclaredConstructor(CTTextBox.class, XWPFDocument.class);
            ctor.setAccessible(true);
            return ctor.newInstance(ctTextBox, document);
        } catch (Exception e) {
            last = e;
        }

