    private static RenderContext instantiateRenderContext(XWPFRun run, XWPFParagraph paragraph, XWPFDocument document) throws Exception {
        Constructor<?>[] constructors = RenderContext.class.getDeclaredConstructors();
        if (constructors.length == 0) {
            constructors = new Constructor<?>[] { RenderContext.class.getDeclaredConstructor() };
        }

        int[] scores = new int[constructors.length];
        int[] lengths = new int[constructors.length];

        for (int i = 0; i < constructors.length; i++) {
            Class<?>[] parameterTypes = constructors[i].getParameterTypes();
            lengths[i] = parameterTypes.length;

            boolean hasRun = false;
            boolean hasSelf = false;
            for (Class<?> parameterType : parameterTypes) {
                if (XWPFRun.class.isAssignableFrom(parameterType)) {
                    hasRun = true;
                }
                if (RenderContext.class.isAssignableFrom(parameterType)) {
                    hasSelf = true;
                }
            }

            int score = 0;
            if (hasRun) {
                score += 3;
            }
            if (parameterTypes.length == 0) {
                score += 1;
            }
            if (hasSelf) {
                score -= 3;
            }
            scores[i] = score;
        }

        for (int i = 0; i < constructors.length - 1; i++) {
            int best = i;
            for (int j = i + 1; j < constructors.length; j++) {
                if (scores[j] > scores[best] || (scores[j] == scores[best] && lengths[j] < lengths[best])) {
                    best = j;
                }
            }
            if (best != i) {
                Constructor<?> constructor = constructors[i];
                constructors[i] = constructors[best];
                constructors[best] = constructor;

                int score = scores[i];
                scores[i] = scores[best];
                scores[best] = score;

                int length = lengths[i];
                lengths[i] = lengths[best];
                lengths[best] = length;
            }
        }

        Throwable lastFailure = null;

        for (int pass = 0; pass < 2; pass++) {
            boolean mockUnknown = pass == 1;

            for (Constructor<?> constructor : constructors) {
                try {
                    RenderContext context = instantiateConstructor(constructor, run, paragraph, document, mockUnknown);
                    injectRun(context, run);
                    context.getContainer();
                    return context;
                } catch (Throwable failure) {
                    lastFailure = failure;
                }
            }
        }

        if (lastFailure instanceof Exception) {
            throw (Exception) lastFailure;
        }
        if (lastFailure instanceof Error) {
            throw (Error) lastFailure;
        }
        throw new Exception(lastFailure);
    }

    private static RenderContext instantiateConstructor(Constructor<?> constructor, XWPFRun run, XWPFParagraph paragraph, XWPFDocument document, boolean mockUnknown) throws Exception {
        constructor.setAccessible(true);
        Class<?>[] parameterTypes = constructor.getParameterTypes();
        Object[] arguments = new Object[parameterTypes.length];

        for (int i = 0; i < parameterTypes.length; i++) {
