        }
        if (type == Boolean.class) {
            return false;
        }
        if (type == Byte.class) {
            return (byte) 0;
        }
        if (type == Character.class) {
            return '\0';
        }
        if (type == Short.class) {
            return (short) 0;
        }
        if (type == Integer.class) {
            return 0;
        }
        if (type == Long.class) {
            return 0L;
        }
        if (type == Float.class) {
            return 0.0f;
        }
        if (type == Double.class) {
            return 0.0d;
        }
        if (mockUnknown) {
            try {
                return Mockito.mock(type);
            } catch (Throwable ignored) {
                return null;
            }
        }
        return null;
    }

    private static Object primitiveDefaultValue(Class<?> type) {
        if (type == boolean.class) {
            return false;
        }
        if (type == byte.class) {
