        }
        if (type == double.class) {
            return 0.0d;
        }
        return null;
    }

    private static void injectRun(RenderContext context, XWPFRun run) throws Exception {
        Class<?> type = context.getClass();
        while (type != null) {
            for (Field field : type.getDeclaredFields()) {
                if (Modifier.isStatic(field.getModifiers())) {
                    continue;
                }
