package com.deepoove.poi.xwpf;

import java.lang.reflect.Field;
import java.util.ArrayList;
import java.util.List;

import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.apache.poi.xwpf.usermodel.XWPFTable;
import org.apache.poi.xwpf.usermodel.XWPFTableCell;
import org.apache.poi.xwpf.usermodel.XWPFTableRow;
import org.junit.jupiter.api.Test;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTbl;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTc;

public class CellBodyContainersetTable_XWPFTableCellgetCTTcFikaTest {

    @Test
    public void testSetTableReachesGetCTTc() throws Exception {
        XWPFDocument document = new XWPFDocument();
        XWPFTable outerTable = document.createTable();

        XWPFTableRow row = outerTable.getRows().isEmpty()
                ? outerTable.createRow()
                : outerTable.getRows().get(0);
        XWPFTableCell cell = row.createCell();

        CTTc ctTc = null;
        try {
            Field ctTcField = XWPFTableCell.class.getDeclaredField("ctTc");
            ctTcField.setAccessible(true);
            Object value = ctTcField.get(cell);
            if (value instanceof CTTc) {
                ctTc = (CTTc) value;
            }
        } catch (NoSuchFieldException e) {
            for (Field field : XWPFTableCell.class.getDeclaredFields()) {
                if (CTTc.class.isAssignableFrom(field.getType())) {
                    field.setAccessible(true);
                    Object value = field.get(cell);
                    if (value instanceof CTTc) {
                        ctTc = (CTTc) value;
                        break;
                    }
                }
            }
        }

        if (ctTc == null) {
            ctTc = cell.getCTTc();
        }

        if (ctTc.sizeOfTblArray() == 0) {
            ctTc.addNewTbl();
        }

        CTTbl innerTbl = ctTc.getTblArray(0);
        XWPFTable table = new XWPFTable(innerTbl, document, 0);

        boolean tablesSet = false;
        try {
            Field tablesField = XWPFTableCell.class.getDeclaredField("tables");
            tablesField.setAccessible(true);
            List<XWPFTable> tables = new ArrayList<>();
            tables.add(table);
            tablesField.set(cell, tables);
            tablesSet = true;
        } catch (NoSuchFieldException | IllegalAccessException e) {
            tablesSet = false;
        }

        if (!tablesSet) {
            List<XWPFTable> tables = cell.getTables();
            if (tables != null && tables.isEmpty()) {
                tables.add(table);
            }
        }

        CellBodyContainer container = new CellBodyContainer(cell);
        container.setTable(0, table);
    }
}

