/**
 * Removes a specific paragraph from this textbox
 *
 * @param paragraph
 * 		- {@link XWPFParagraph} object to remove
 */
public void removeParagraph(XWPFParagraph paragraph) {
    if (paragraphs.contains(paragraph)) // PATH: Test should invoke the next XmlCursor.dispose(...) [step in execution path]
    {
        CTP ctP = paragraph.getCTP();
        XmlCursor c = ctP.newCursor();
        c.removeXml();
        c.dispose();
        paragraphs.remove(paragraph);
        sdtElements.remove(paragraph);
    }
}

