import java.util.List;

public class HelperrenderTable_XWPFTablegetRowsFikaTest {

    @Test
    public void testRenderTable() throws Exception {
        XWPFDocument document = new XWPFDocument();
        XWPFParagraph paragraph = document.createParagraph();
        XWPFRun run = paragraph.createRun();

        List<RowRenderData> rows = new ArrayList<>();
        RowRenderData row = Mockito.mock(RowRenderData.class);
        rows.add(row);

        TableStyle tableStyle = Mockito.mock(TableStyle.class);
        MergeRule mergeRule = Mockito.mock(MergeRule.class);

        TableRenderData data = Mockito.mock(TableRenderData.class);
        Mockito.when(data.obtainRowSize()).thenReturn(1);
        Mockito.when(data.obtainColSize()).thenReturn(1);
        Mockito.when(data.getTableStyle()).thenReturn(tableStyle);
        Mockito.when(data.getRows()).thenReturn(rows);
        Mockito.when(data.getMergeRule()).thenReturn(mergeRule);

        TableRenderPolicy.Helper.renderTable(run, data);

        document.close();
    }
}

