import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.*;

public class XWPFDocumentIteratornext_CollectionUtilsisEmptyFikaTest {

    @Test
    public void testNextInvokesCollectionUtilsIsEmpty() throws Exception {
        // Create mock dependencies for DocxRenderPolicy constructor
        List<MetaTemplate> mockTemplates = new ArrayList<>();
        Map<String, Object> mockDatas = new HashMap<>();
        XWPFTemplate.Config mockConfig = Mockito.mock(XWPFTemplate.Config.class);

        // Create the outer DocxRenderPolicy instance
        DocxRenderPolicy renderPolicy = new DocxRenderPolicy(mockTemplates, mockDatas, mockConfig);

        // Get the iterator from the policy
        Iterator<NiceXWPFDocument> iterator = renderPolicy.iterator();

        // Prepare test data - empty datas to trigger the CollectionUtils.isEmpty() path
        byte[] templateBytes = "Test template content".getBytes();

        // Use reflection to set up the iterator's internal state
        java.lang.reflect.Field bytesField = iterator.getClass().getDeclaredField("bytes");
        bytesField.setAccessible(true);
        bytesField.set(iterator, templateBytes);

        java.lang.reflect.Field datasField = iterator.getClass().getDeclaredField("datas");
        datasField.setAccessible(true);
        datasField.set(iterator, new ArrayList<Map<String, Object>>());

        java.lang.reflect.Field configField = iterator.getClass().getDeclaredField("config");
        configField.setAccessible(true);
        configField.set(iterator, mockConfig);

        // Call next() which should invoke CollectionUtils.isEmpty()
        iterator.next();
