    @Test
    public void testRemoveBodyElement() throws Exception {
        // Create a real IBodyElement that will return a non-null element type
        IBodyElement mockBodyElement = Mockito.mock(IBodyElement.class);
        Mockito.when(mockBodyElement.getElementType()).thenReturn(BodyElementType.PARAGRAPH);

        // Create a list with the mock element
        List<IBodyElement> bodyElements = new ArrayList<>();
        bodyElements.add(mockBodyElement);

        // Create mock CTSdtContentBlock for constructor
