        // Use reflection to set the body elements for testing
        java.lang.reflect.Field field = SDTBodyContainer.class.getDeclaredField("bodyElements");
        field.setAccessible(true);
        field.set(container, bodyElements);

        // Invoke the entry point method - this should trigger getElementType() call
        container.removeBodyElement(0);
    }

    // Minimal implementation of SDTBodyContainer to make the test compile
    private static class SDTBodyContainer {
