    @Test
    public void testUpdateDocPrIdTriggersDocumentFactoryParse() throws Exception {
        // Create mock NiceXWPFDocument with valid DocPrIdenifierManager
        NiceXWPFDocument mockDocument = Mockito.mock(NiceXWPFDocument.class);
        Object mockManager = Mockito.mock(Object.class);
        Field isValidField = mockManager.getClass().getSuperclass().getDeclaredField("valid");
        isValidField.setAccessible(true);
        isValidField.set(mockManager, true);

        Mockito.when(mockDocument.getDocPrIdenifierManager()).thenReturn(mockManager);

        // Create XWPFRun that returns our mock document
        XWPFRun mockRun = Mockito.mock(XWPFRun.class);
        Mockito.when(mockRun.getDocument()).thenReturn(mockDocument);

        // Create CTR with drawing list and XML objects
        Object mockCTR = Mockito.mock(Object.class);
        Object mockDrawing = Mockito.mock(Object.class);
        Object[] drawingArray = new Object[]{mockDrawing};

        Mockito.when(mockRun.getCTR()).thenReturn(mockCTR);

        // Setup drawing list
        Field drawingListField = mockCTR.getClass().getDeclaredField("drawingList");
        drawingListField.setAccessible(true);
        drawingListField.set(mockCTR, drawingArray);

        // Setup XML objects that will trigger CTDrawing.Factory.parse()
        XmlObject mockXmlObject = Mockito.mock(XmlObject.class);
        Mockito.when(mockXmlObject.xmlText()).thenReturn("<xml>test</xml>");
        XmlObject[] xmlObjects = new XmlObject[]{mockXmlObject};

        // Setup selectPath to return XML objects
        Field selectPathField = mockCTR.getClass().getDeclaredField("selectPathResult");
        selectPathField.setAccessible(true);
        selectPathField.set(mockCTR, xmlObjects);

        // Invoke the entry point method
        DrawingSupport.updateDocPrId(mockRun);
    }
}

