import com.deepoove.poi.template.run.RunTemplate;
import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.apache.poi.xwpf.usermodel.XWPFRun;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTR;

import java.io.ByteArrayInputStream;
import java.util.HashMap;

public class AttachmentRenderPolicydoRender_InputSourcemethodFikaTest {

    @Test
    public void testDoRender() throws Exception {
        AttachmentRenderPolicy policy = new AttachmentRenderPolicy();

        XWPFDocument document = new XWPFDocument();
        XWPFRun run = document.createParagraph().createRun();
        CTR ctr = run.getCTR();

        RunTemplate runTemplate = Mockito.mock(RunTemplate.class);
        Mockito.when(runTemplate.getRun()).thenReturn(run);

        Configure config = Configure.createDefault();
        XWPFTemplate template = Mockito.mock(XWPFTemplate.class);
        Mockito.when(template.getConfig()).thenReturn(config);
        Mockito.when(template.getXWPFDocument()).thenReturn(document);

        byte[] testData = "test content".getBytes();
        AttachmentRenderData data = new AttachmentRenderData(
            AttachmentType.XLSX, 
            "test.xlsx", 
            new ByteArrayInputStream(testData)
        ) {
            @Override
            public byte[] readAttachmentData() {
                return testData;
            }

            @Override
            public PictureRenderData getIcon() {
                return Pictures.ofBase64("iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNkYPhfDwAChwGA60e6kgAAAABJRU5ErkJggg==")
                    .size(64, 64)
                    .create();
            }
        };

        RenderContext<AttachmentRenderData> context = new RenderContext<>(
            runTemplate, 
            new HashMap<>(), 
            template, 
            data
        );

        policy.doRender(context);
    }
}

