") + "                        <v:imagedata r:id=\"") + imageRId) + "\" o:title=\"\"/>
") + "                    </v:shape>
") + "                    <o:OLEObject Type=\"Embed\" ProgID=\"") + fileType.programId()) + "\" ShapeID=\"") + shapeId) + "\" DrawAspect=\"Icon\" ObjectID=\"") + shapeId) + "\" r:id=\"") + embeddId) + "\">
") + "                     <o:FieldCodes>\\s</o:FieldCodes>
