import org.apache.xmlbeans.XmlCursor;
import org.apache.xmlbeans.XmlObject;

public class CTDrawingWrappergetChartId_CTDrawinggetAnchorArrayFikaTest {

    @Test
    public void testGetChartIdInvokesGetAnchorArray() throws Exception {
        CTDrawing ctDrawing = Mockito.mock(CTDrawing.class);
        Mockito.when(ctDrawing.sizeOfAnchorArray()).thenReturn(1);

        CTAnchor mockAnchor = Mockito.mock(CTAnchor.class);
        CTGraphicalObject mockGraphic = Mockito.mock(CTGraphicalObject.class);
        CTGraphicalObjectData mockGraphicData = Mockito.mock(CTGraphicalObjectData.class);
        XmlCursor mockCursor = Mockito.mock(XmlCursor.class);
        CTRelId mockRelId = Mockito.mock(CTRelId.class);

        Mockito.when(ctDrawing.getAnchorArray(0)).thenReturn(mockAnchor);
        Mockito.when(mockAnchor.getGraphic()).thenReturn(mockGraphic);
        Mockito.when(mockGraphic.getGraphicData()).thenReturn(mockGraphicData);
        Mockito.when(mockGraphicData.newCursor()).thenReturn(mockCursor);
        Mockito.when(mockCursor.toChild(0)).thenReturn(true);
        Mockito.when(mockCursor.getObject()).thenReturn(mockRelId);
        Mockito.when(mockRelId.getId()).thenReturn("test-id");

        CTDrawingWrapper wrapper = new CTDrawingWrapper(ctDrawing);
        wrapper.getChartId();
    }
}

