        CTTblWidth tw = (tPr.isSetTblInd()) ? tPr.getTblInd() : tPr.addNewTblInd();
        tw.setType(STTblWidth.DXA);
        tw.setW(BigInteger.valueOf(UnitUtils.cm2Twips(tableStyle.getIndentation())));
