        // Create mock cursor
        XmlCursor cursor = mock(XmlCursor.class);

        // Create mock CTP object
        CTP mockCTP = mock(CTP.class);
        XmlCursor mockCTPCursor = mock(XmlCursor.class);
        when(mockCTP.newCursor()).thenReturn(mockCTPCursor);

        // Setup cursor behavior to simulate being in textbox
        when(cursor.getObject()).thenReturn(mockCTP);
        when(cursor.toPrevSibling()).thenReturn(false);
        when(cursor.toParent()).thenReturn(cursor);

        // Create mock XWPFTextboxContent
        XWPFTextboxContent textboxContent = mock(XWPFTextboxContent.class);

        // Setup the insertNewParagraph method to call real method
        when(textboxContent.insertNewParagraph(cursor)).thenCallRealMethod();

        // Setup isCursorInTextBox to return true
        when(textboxContent.isCursorInTextBox(cursor)).thenReturn(true);

        // Setup getParagraph method to return null (simplified for test)
        when(textboxContent.getParagraph(any(CTP.class))).thenReturn(null);

        // Execute the entry point method
        textboxContent.insertNewParagraph(cursor);
    }
}

