import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;

public class TableToolswidthTable_CTTblWidthsetWFikaTest {

    @Test
    public void testWidthTableInvokesSetW() throws Exception {
        XWPFDocument document = new XWPFDocument();
        XWPFTable table = document.createTable();

        CTTbl ctTbl = table.getCTTbl();
        CTTblPr tblPr = ctTbl.isSetTblPr() ? ctTbl.getTblPr() : ctTbl.addNewTblPr();
        CTTblWidth tblW = tblPr.isSetTblW() ? tblPr.getTblW() : tblPr.addNewTblW();

        CTTblGrid tblGrid = ctTbl.isSetTblGrid() ? ctTbl.getTblGrid() : ctTbl.addNewTblGrid();

        XWPFTableRow row = table.getRow(0);
        if (row == null) {
            row = table.createRow();
        }

        while (row.getTableCells().size() < 2) {
            row.createCell();
        }

        float[] colWidths = new float[] { 5.0f, 5.0f };

        TableTools.widthTable(table, colWidths);
    }
}

