package com.deepoove.poi.policy.reference;

import com.deepoove.poi.XWPFTemplate;
import com.deepoove.poi.data.ChartMultiSeriesRenderData;
import com.deepoove.poi.data.SeriesRenderData;
import com.deepoove.poi.template.ChartTemplate;
import org.apache.poi.xddf.usermodel.chart.XDDFChartData;
import org.apache.poi.xddf.usermodel.chart.XDDFDataSource;
import org.apache.poi.xddf.usermodel.chart.XDDFNumericalDataSource;
import org.apache.poi.xwpf.usermodel.XWPFChart;
import org.apache.poi.xssf.usermodel.XSSFSheet;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.util.ArrayList;
import java.util.List;

public class MultiSeriesChartTemplateRenderPolicydoRender_XWPFChartsetSheetTitleFikaTest {

    @Test
    public void testDoRender() throws Exception {
        // Create the policy instance
        MultiSeriesChartTemplateRenderPolicy policy = new MultiSeriesChartTemplateRenderPolicy();

        // Create mock ChartTemplate
        ChartTemplate chartTemplate = Mockito.mock(ChartTemplate.class);
        XWPFChart mockChart = Mockito.mock(XWPFChart.class);
        Mockito.when(chartTemplate.getChart()).thenReturn(mockChart);

        // Create mock chart series
        List<XDDFChartData> chartSeries = new ArrayList<>();
        XDDFChartData mockChartData = Mockito.mock(XDDFChartData.class);
        chartSeries.add(mockChartData);
        Mockito.when(mockChart.getChartSeries()).thenReturn(chartSeries);

        // Configure mock chart data behavior
        Mockito.when(mockChartData.getSeriesCount()).thenReturn(1);
        List<XDDFChartData.Series> mockSeriesList = new ArrayList<>();
        XDDFChartData.Series mockSeries = Mockito.mock(XDDFChartData.Series.class);
        mockSeriesList.add(mockSeries);
        Mockito.when(mockChartData.getSeries(Mockito.anyInt())).thenReturn(mockSeries);

        // Mock data source for series
        XDDFDataSource<?> mockDataSource = Mockito.mock(XDDFDataSource.class);
        Mockito.when(mockSeries.getValuesData()).thenReturn(mockDataSource);
        Mockito.when(mockDataSource.getFormatCode()).thenReturn("General");

        // Create mock XWPFTemplate
        XWPFTemplate template = Mockito.mock(XWPFTemplate.class);

        // Create test data
        ChartMultiSeriesRenderData data = new ChartMultiSeriesRenderData();
        data.setChartTitle("Test Chart");
        data.setxAxisTitle("X Axis");
        data.setyAxisTitle("Y Axis");

        // Set categories
        String[] categories = new String[]{"Cat1", "Cat2", "Cat3"};
        data.setCategories(categories);

        // Create series data
        List<SeriesRenderData> seriesDatas = new ArrayList<>();
        SeriesRenderData series1 = new SeriesRenderData();
        series1.setName("Series1");
        series1.setValues(new Double[]{1.0, 2.0, 3.0});
        seriesDatas.add(series1);
        data.setSeriesDatas(seriesDatas);

        // Mock workbook and sheet for chart
        XSSFSheet mockSheet = Mockito.mock(XSSFSheet.class);
        Mockito.when(mockChart.getWorkbook()).thenReturn(Mockito.mock(org.apache.poi.xssf.usermodel.XSSFWorkbook.class));
        Mockito.when(mockChart.getWorkbook().getSheetAt(0)).thenReturn(mockSheet);

        // Execute the entry point method
        policy.doRender(chartTemplate, data, template);
    }
}

