public class NumberingContinueupdateNumbering_CTAbstractNumsetAbstractNumIdFikaTest {

    @Test
    public void testUpdateNumbering() throws Exception {
        // Create real document and numbering
        XWPFDocument document = new XWPFDocument();
        XWPFNumbering numbering = document.createNumbering();

        // Create real source paragraph
        XWPFParagraph source = document.createParagraph();

        // Create real target paragraph
        XWPFParagraph target = document.createParagraph();

        // Create real abstract num and add to numbering
        CTAbstractNum ctAbstractNum = CTAbstractNum.Factory.newInstance();
        BigInteger abstractNumId = BigInteger.valueOf(1);
        ctAbstractNum.setAbstractNumId(abstractNumId);
        XWPFAbstractNum abstractNum = new XWPFAbstractNum(ctAbstractNum);
        BigInteger addedAbstractNumId = numbering.addAbstractNum(abstractNum);

        // Create real num and add to numbering
        BigInteger numId = BigInteger.valueOf(100);
        BigInteger addedNumId = numbering.addNum(addedAbstractNumId);

        // Set numID on source paragraph
        source.setNumID(addedNumId);

        // Create NumberingContinue instance with mocked consistCache
        HashMap<BigInteger, BigInteger> consistCache = new HashMap<>();
        NumberingContinue numberingContinue = new NumberingContinue(consistCache);

        // Execute the entry point method
        numberingContinue.updateNumbering(source, target);
    }
}

