package com.deepoove.poi.plugin.table;

import com.deepoove.poi.XWPFTemplate;
import com.deepoove.poi.template.ElementTemplate;
import com.deepoove.poi.template.run.RunTemplate;
import org.apache.poi.xwpf.usermodel.*;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.util.Arrays;
import java.util.List;

public class LoopColumnTableRenderPolicyrender_XWPFRunsetTextFikaTest {

    @Test
    public void testRender() throws Exception {
        // Create real XWPFRun
        XWPFDocument document = new XWPFDocument();
        XWPFParagraph paragraph = document.createParagraph();
        XWPFRun realRun = paragraph.createRun();
        realRun.setText("initial", 0);

        // Create RunTemplate with real run
        RunTemplate runTemplate = Mockito.mock(RunTemplate.class);
        Mockito.when(runTemplate.getRun()).thenReturn(realRun);
        Mockito.when(runTemplate.getSource()).thenReturn("{{test}}");

        // Create table structure
        XWPFTable table = document.createTable(2, 3);
        XWPFTableRow row = table.getRow(0);
        XWPFTableCell cell = row.getCell(0);

        // Get paragraph from cell and replace its run with our real run
        XWPFParagraph cellParagraph = cell.getParagraphs().get(0);
        cellParagraph.removeRun(0);
        cellParagraph.getRuns().add(realRun);

        // Mock ElementTemplate
        ElementTemplate eleTemplate = Mockito.mock(ElementTemplate.class);

        // Create XWPFTemplate with minimal configuration
        XWPFTemplate template = Mockito.mock(XWPFTemplate.class);
        XWPFTemplate.XWPFTemplateConfig config = Mockito.mock(XWPFTemplate.XWPFTemplateConfig.class);
        Mockito.when(template.getConfig()).thenReturn(config);

        // Mock render data compute factory
        XWPFTemplate.RenderDataComputeFactory factory = Mockito.mock(XWPFTemplate.RenderDataComputeFactory.class);
        Mockito.when(config.getRenderDataComputeFactory()).thenReturn(factory);

        // Mock render data compute
        XWPFTemplate.RenderDataCompute dataCompute = Mockito.mock(XWPFTemplate.RenderDataCompute.class);
        Mockito.when(factory.newCompute(Mockito.any())).thenReturn(dataCompute);

        // Create test data
        List<String> data = Arrays.asList("col1", "col2");

        // Create policy and execute
        LoopColumnTableRenderPolicy policy = new LoopColumnTableRenderPolicy();
        policy.render(runTemplate, data, template);
    }
}

