    @Test
    public void testRenderPictureInvokesSetAlignment() throws Exception {
        // Create a real XWPFParagraph mock since it's required for setAlignment call
        XWPFParagraph paragraph = Mockito.mock(XWPFParagraph.class);

        // Create a mock XWPFRun that returns the paragraph as parent
