        // Set picture type to PNG to avoid SVG conversion path
        Mockito.when(picture.getPictureType()).thenReturn(PictureType.PNG);

        // Create a PictureStyle with alignment to trigger the setAlignment call
        PictureStyle style = new PictureStyle();
        style.setAlign(PictureAlign.CENTER);

        // Mock the style retrieval
        Mockito.when(picture.getPictureStyle()).thenReturn(style);

        // Execute the entry point method
        com.deepoove.poi.policy.PictureRenderPolicy.Helper.renderPicture(run, picture);

