        XWPFTable table = Mockito.mock(XWPFTable.class);
        XWPFTableRow row = Mockito.mock(XWPFTableRow.class);
        org.apache.poi.xwpf.usermodel.XWPFTableCell cell = Mockito.mock(org.apache.poi.xwpf.usermodel.XWPFTableCell.class);

        Mockito.when(table.getWidthType()).thenReturn(TableWidthType.DXA);
        Mockito.when(table.getRows()).thenReturn(Arrays.asList(row));
