package com.deepoove.poi.util;

import org.junit.jupiter.api.Test;
import org.apache.poi.xwpf.usermodel.XWPFTable;
import org.apache.poi.xwpf.usermodel.XWPFTableRow;
import org.apache.poi.xwpf.usermodel.XWPFTableCell;
import org.apache.poi.xwpf.usermodel.TableWidthType;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTbl;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTblGrid;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTblPr;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTblWidth;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.STTblWidth;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTblLayoutType;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.STTblLayoutType;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTblGridCol;
import java.math.BigInteger;
import java.util.ArrayList;
import java.util.List;

public class TableToolssetWidth_CTTblGridaddNewGridColFikaTest {

    @Test
    public void testSetWidthTriggersAddNewGridCol() throws Exception {
        XWPFTable table = createTestTable();

        int[] colWidths = new int[]{1000, 2000};
        TableTools.setWidth(table, "3000", colWidths);
    }

    private XWPFTable createTestTable() {
        CTTbl ctTbl = CTTbl.Factory.newInstance();
        CTTblPr tblPr = ctTbl.addNewTblPr();
        CTTblWidth tblWidth = tblPr.addNewTblW();
        tblWidth.setType(STTblWidth.DXA);
        tblWidth.setW(BigInteger.valueOf(3000));

        CTTblGrid tblGrid = ctTbl.addNewTblGrid();
        CTTblLayoutType layout = tblPr.addNewTblLayout();
        layout.setType(STTblLayoutType.FIXED);

        XWPFTable table = new XWPFTable(ctTbl, null);
        table.setWidthType(TableWidthType.DXA);

        List<XWPFTableRow> rows = new ArrayList<>();
        for (int i = 0; i < 2; i++) {
            XWPFTableRow row = new XWPFTableRow(ctTbl.addNewTr(), table);
            for (int j = 0; j < 2; j++) {
                XWPFTableCell cell = new XWPFTableCell(ctTbl.getTrArray(i).addNewTc(), row, null);
                row.addCell(cell);
            }
            rows.add(row);
        }

        table.setRows(rows);
        return table;
    }
}

