package com.deepoove.poi.util;

import org.apache.poi.xwpf.usermodel.XWPFParagraph;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import static org.mockito.Mockito.when;

public class StyleUtilsretriveParagraphStyle_XWPFParagraphgetSpacingLineRuleFikaTest {

    @Test
    public void testRetriveParagraphStyle() {
        XWPFParagraph paragraph = Mockito.mock(XWPFParagraph.class);

        org.apache.poi.xwpf.usermodel.CTP ctp = Mockito.mock(org.apache.poi.xwpf.usermodel.CTP.class);
        org.apache.poi.xwpf.usermodel.CTPPr pr = Mockito.mock(org.apache.poi.xwpf.usermodel.CTPPr.class);

        when(paragraph.getCTP()).thenReturn(ctp);
        when(ctp.isSetPPr()).thenReturn(true);
        when(ctp.getPPr()).thenReturn(pr);

        when(paragraph.isWordWrapped()).thenReturn(false);
        when(pr.isSetPBdr()).thenReturn(false);
        when(pr.isSetShd()).thenReturn(false);

        when(paragraph.getAlignment()).thenReturn(null);
        when(paragraph.getSpacingBeforeLines()).thenReturn(-1);
        when(paragraph.getSpacingAfterLines()).thenReturn(-1);
        when(paragraph.getSpacingBefore()).thenReturn(-1);
        when(paragraph.getSpacingAfter()).thenReturn(-1);

        when(paragraph.getSpacingBetween()).thenReturn(1.0);
        when(paragraph.getSpacingLineRule()).thenReturn(null);

        StyleUtils.retriveParagraphStyle(paragraph);
    }
}

