package com.deepoove.poi.util;

import com.deepoove.poi.data.style.ParagraphStyle;
import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.apache.poi.xwpf.usermodel.XWPFParagraph;
import org.junit.jupiter.api.Test;

import java.math.BigInteger;

public class StyleUtilsstylePpr_CTPBdrisSetTopFikaTest {

    @Test
    public void testStylePprInvokesCTPBdrIsSetTop() throws Exception {
        XWPFDocument document = new XWPFDocument();
        XWPFParagraph paragraph = document.createParagraph();

        ParagraphStyle style = ParagraphStyle.builder()
                .withTopBorder(com.deepoove.poi.data.style.BorderStyle.builder()
                        .withColor("#000000")
                        .withSize(1)
                        .withType(com.deepoove.poi.data.style.BorderStyle.BorderStyleType.SINGLE)
                        .build())
                .build();

        StyleUtils.stylePpr(paragraph, style);

        document.close();
    }
}

