package com.deepoove.poi.plugin.table;

import com.deepoove.poi.XWPFTemplate;
import com.deepoove.poi.template.ElementTemplate;
import com.deepoove.poi.template.run.RunTemplate;
import org.apache.poi.xwpf.usermodel.*;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.math.BigInteger;

public class RemoveTableColumnRenderPolicyminusGridSpan_CTTcPrgetGridSpanFikaTest {

    @Test
    public void testRenderPathToGetGridSpan() throws Exception {
        // Create the class under test
        RemoveTableColumnRenderPolicy policy = new RemoveTableColumnRenderPolicy();

        // Create mock template
        XWPFTemplate template = Mockito.mock(XWPFTemplate.class);

        // Create a real table structure
        XWPFDocument document = new XWPFDocument();
        XWPFTable table = document.createTable(2, 3);

        // Get the cell that will be used as the tag cell
        XWPFTableRow firstRow = table.getRow(0);
        XWPFTableCell tagCell = firstRow.getCell(1);

        // Create a paragraph and run inside the tag cell
        XWPFParagraph paragraph = tagCell.addParagraph();
        XWPFRun run = paragraph.createRun();
        run.setText("test");

        // Create the element template
        RunTemplate runTemplate = Mockito.mock(RunTemplate.class);
        Mockito.when(runTemplate.getRun()).thenReturn(run);

        // Set up the template to return the tag cell's paragraph as parent
        // This ensures TableTools.isInsideTable returns true
        Mockito.when(run.getParent()).thenReturn(paragraph);

        // Create a row where actualInsertPosition will be -1
        XWPFTableRow secondRow = table.getRow(1);
        // Remove cells to make actualInsertPosition -1
        secondRow.removeCell(1);
        secondRow.removeCell(1);

        // Add grid span to a cell to ensure getGridSpan() is called
        XWPFTableCell spannedCell = secondRow.getCell(0);
        org.openxmlformats.schemas.wordprocessingml.x2006.main.CTTcPr tcPr = 
            spannedCell.getCTTc().isSetTcPr() ? 
            spannedCell.getCTTc().getTcPr() : 
            spannedCell.getCTTc().addNewTcPr();
        tcPr.addNewGridSpan().setVal(BigInteger.valueOf(2));

        // Execute the render method
        policy.render(runTemplate, null, template);

        // Clean up
        document.close();
    }
}

