    if (cell == null) {
        return;
    }
    XmlCursor cursor = cell.newCursor();
    cursor.selectPath("./*");
    while (cursor.toNextSelection()) {
        XmlObject o = cursor.getObject();
        if (o instanceof CTTc) {
