    @Test
    public void testDoRenderToPlotToUnsetNumRef() throws Exception {
        // Create mocks for dependencies
        ChartTemplate chartTemplate = mock(ChartTemplate.class);
        ChartSingleSeriesRenderData chartData = mock(ChartSingleSeriesRenderData.class);
        XWPFTemplate xwpfTemplate = mock(XWPFTemplate.class);
        XWPFChart xwpfChart = mock(XWPFChart.class);
        SeriesRenderData seriesData = mock(SeriesRenderData.class);

        // Mock chart retrieval
        when(chartTemplate.getChart()).thenReturn(xwpfChart);

        // Mock chart data series
        XDDFChartData chartSeries = mock(XDDFChartData.class);
        XDDFChartData.Series series = mock(XDDFChartData.Series.class);
        when(chartSeries.getSeries(anyInt())).thenReturn(series);

        // Mock categories and values
        when(chartData.getCategories()).thenReturn(Arrays.asList("Cat1", "Cat2"));
        when(chartData.getSeriesData()).thenReturn(seriesData);
        when(seriesData.getValues()).thenReturn(Arrays.asList(10.0, 20.0));
        when(seriesData.getName()).thenReturn("TestSeries");

        // Mock data sources
        XDDFDataSource<?> stringDataSource = mock(XDDFDataSource.class);
        when(stringDataSource.isNumeric()).thenReturn(false);

        XDDFNumericalDataSource<?> numericalDataSource = mock(XDDFNumericalDataSource.class);

        // Mock series category data to be non-numeric (to trigger unsetNumRef path)
        when(series.getCategoryData()).thenReturn(stringDataSource);

        // Create the policy instance
        SingleSeriesChartTemplateRenderPolicy policy = new SingleSeriesChartTemplateRenderPolicy();

        // Use reflection to set up the chart series in ChartUtils
        // Since ChartUtils.getChartSeries is static and package-private, we need to ensure
        // the chart returns the mocked series when requested
        // We'll create a custom chart that returns our mocked series
        org.apache.poi.xssf.usermodel.XSSFWorkbook workbook = new org.apache.poi.xssf.usermodel.XSSFWorkbook();
        org.apache.poi.xssf.usermodel.XSSFSheet sheet = workbook.createSheet();

        // Create a real XWPFChart with the workbook
        XWPFChart realChart = new XWPFChart(sheet.createDrawingPatriarch(), null) {
            @Override
            public org.apache.poi.xssf.usermodel.XSSFWorkbook getWorkbook() {
                return workbook;
            }
        };

        when(chartTemplate.getChart()).thenReturn(realChart);

        // Create a real XDDFChartData series that will trigger the unsetNumRef path
        XDDFChartData realChartData = new XDDFScatterChartData(realChart) {
            @Override
            public java.util.List<XDDFChartData.Series> getSeries() {
                return Collections.singletonList(series);
            }

            @Override
            public XDDFChartData.Series getSeries(int index) {
                return series;
            }
        };

        // Use reflection to set up the chart series in the chart
        // We need to make sure ChartUtils.getChartSeries returns our realChartData
        // Since we can't mock static methods, we'll create a scenario where
        // the chart has our data
        Method setChartDataMethod = XWPFChart.class.getDeclaredMethod("setChartData", XDDFChartData.class);
        setChartDataMethod.setAccessible(true);
        setChartDataMethod.invoke(realChart, realChartData);

        // Execute the entry point
        policy.doRender(chartTemplate, chartData, xwpfTemplate);
    }
}

