        XWPFTable table = new XWPFTable(null, null);
        XWPFTableRow row = new XWPFTableRow(null, table);
        XWPFTableCell cell = new XWPFTableCell(null, row, null);
        row.getTableCells().add(cell);
        table.getRows().add(row);

        // Create the content object with the table in sdtElements
