        XWPFStructuredDocumentTagContent content = new XWPFStructuredDocumentTagContent(sdtElements);

        // This will trigger the call chain: getText() -> appendTable() -> table.getRows()
        content.getText();
    }

    // Helper class to make the test compile
    private static class XWPFStructuredDocumentTagContent {
        private final List<Object> sdtElements;

        public XWPFStructuredDocumentTagContent(List<Object> sdtElements) {
            this.sdtElements = sdtElements;
        }

        public String getText() {
            StringBuilder text = new StringBuilder();
            boolean addNewLine = false;
            for (int i = 0; i < sdtElements.size(); i++) {
                Object o = sdtElements.get(i);
                if (o instanceof XWPFParagraph) {
                    appendParagraph(((XWPFParagraph) (o)), text);
                    addNewLine = true;
                } else if (o instanceof XWPFTable) {
                    appendTable(((XWPFTable) (o)), text);
                    addNewLine = true;
                } else if (o instanceof XWPFSDT) {
                    text.append(((XWPFSDT) (o)).getContent().getText());
                    addNewLine = true;
                } else if (o instanceof XWPFRun) {
                    text.append(o);
                    addNewLine = false;
                }
                if (addNewLine && (i < (sdtElements.size() - 1))) {
                    text.append("\n");
                }
            }
            return text.toString();
        }

        private void appendTable(XWPFTable table, StringBuilder text) {
            for (XWPFTableRow row : table.getRows()) {
                List<Object> cells = new ArrayList<>();
                for (int i = 0; i < cells.size(); i++) {
                    Object cell = cells.get(i);
                    if (cell instanceof XWPFTableCell) {
                        text.append(((XWPFTableCell) (cell)).getText());
                    } else if (cell instanceof XWPFSDTCell) {
                        text.append(((XWPFSDTCell) (cell)).getContent().getText());
                    }
                    if (i < (cells.size() - 1)) {
                        text.append("\t");
                    }
                }
                text.append('\n');
            }
        }

        private void appendParagraph(XWPFParagraph paragraph, StringBuilder text) {
            text.append(paragraph.getText());
        }
    }

    // Helper class to make the test compile
    private static class XWPFSDTCell {
        public XWPFStructuredDocumentTagContent getContent() {
            return new XWPFStructuredDocumentTagContent(new ArrayList<>());
        }
    }
}

