package com.deepoove.poi.policy.reference;

import com.deepoove.poi.XWPFTemplate;
import com.deepoove.poi.data.ChartMultiSeriesRenderData;
import com.deepoove.poi.template.ChartTemplate;
import org.apache.poi.xssf.usermodel.XSSFSheet;
import org.apache.poi.xssf.usermodel.XSSFRow;
import org.apache.poi.xssf.usermodel.XSSFCell;
import org.apache.poi.xddf.usermodel.chart.XDDFChartData;
import org.apache.poi.xddf.usermodel.chart.XDDFScatterChartData;
import org.apache.poi.xddf.usermodel.chart.XDDFDataSource;
import org.apache.poi.xddf.usermodel.chart.XDDFNumericalDataSource;
import org.apache.poi.xwpf.usermodel.XWPFChart;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.util.ArrayList;
import java.util.List;

public class MultiSeriesChartTemplateRenderPolicy_AbstractChartTemplateRenderPolicyremoveExtraSheetCell_XSSFRowremoveCellFikaTest {

    @Test
    public void testRemoveExtraSheetCellTriggersXSSFRowRemoveCell() throws Exception {
        // Create mocks for required constructor parameters
        XWPFTemplate template = Mockito.mock(XWPFTemplate.class);

        // Create the policy instance
        MultiSeriesChartTemplateRenderPolicy policy = new MultiSeriesChartTemplateRenderPolicy();

        // Mock ChartTemplate
        ChartTemplate chartTemplate = Mockito.mock(ChartTemplate.class);
        XWPFChart chart = Mockito.mock(XWPFChart.class);
        Mockito.when(chartTemplate.getChart()).thenReturn(chart);

        // Mock chart series list
        List<XDDFChartData> chartSeries = new ArrayList<>();
        XDDFChartData chartData = Mockito.mock(XDDFChartData.class);
        chartSeries.add(chartData);
        Mockito.when(chart.getChartSeries()).thenReturn(chartSeries);

        // Mock XSSFSheet
        XSSFSheet sheet = Mockito.mock(XSSFSheet.class);
        Mockito.when(chart.getWorkbook()).thenReturn(Mockito.mock(org.apache.poi.xssf.usermodel.XSSFWorkbook.class));
        Mockito.when(chart.getWorkbook().getSheetAt(0)).thenReturn(sheet);

        // Setup XSSFRow and XSSFCell to trigger removeCell
        XSSFRow row = Mockito.mock(XSSFRow.class);
        XSSFCell cell = Mockito.mock(XSSFCell.class);
        Mockito.when(sheet.getRow(Mockito.anyInt())).thenReturn(row);
        Mockito.when(row.getCell(Mockito.anyInt())).thenReturn(cell);

        // Mock chart data methods
        Mockito.when(chartData.getSeriesCount()).thenReturn(2);
        Mockito.when(chartData.getSeries(Mockito.anyInt())).thenReturn(Mockito.mock(XDDFChartData.Series.class));

        // Mock series data source
        XDDFDataSource<?> categoriesDataSource = Mockito.mock(XDDFDataSource.class);
        Mockito.when(chartData.getSeries(0)).thenReturn(Mockito.mock(XDDFChartData.Series.class));
        Mockito.when(chartData.getSeries(0).getValuesData()).thenReturn(Mockito.mock(XDDFNumericalDataSource.class));

        // Create test data
        ChartMultiSeriesRenderData renderData = ChartMultiSeriesRenderData.builder()
                .categories(new String[]{"Cat1", "Cat2"})
                .build();

        // Add series data
        List<com.deepoove.poi.data.SeriesRenderData> seriesList = new ArrayList<>();
        seriesList.add(com.deepoove.poi.data.SeriesRenderData.builder()
                .name("Series1")
                .values(new Double[]{1.0, 2.0})
                .build());
        renderData.series(seriesList);

        // Execute the entry point method
        policy.doRender(chartTemplate, renderData, template);
    }
}

