    @Test
    public void testRenderTableTriggersGetRow() throws Exception {
        XWPFDocument document = new XWPFDocument();
        XWPFRun run = document.createParagraph().createRun();

        TableRenderData tableRenderData = createTableRenderDataWithMergeRule();

        TableRenderPolicy.Helper.renderTable(run, tableRenderData);
    }

    private TableRenderData createTableRenderDataWithMergeRule() {
        TableRenderData data = TableRenderData.builder()
            .addRow("A1", "B1")
            .addRow("A2", "B2")
            .build();

        MergeCellRule mergeRule = new MergeCellRule() {
            private final Map<Grid, Grid> mapping = new HashMap<>();
            {
                Grid key = new Grid(0, 0);
                Grid value = new Grid(1, 0);
                mapping.put(key, value);
            }

            @Override
            public Iterator<Map.Entry<Grid, Grid>> mappingIterator() {
                return mapping.entrySet().iterator();
            }
        };

        data.setMergeRule(mergeRule);
        return data;
    }
}

