package com.deepoove.poi.policy;

import com.deepoove.poi.data.MergeCellRule;
import com.deepoove.poi.data.TableRenderData;
import com.deepoove.poi.data.RowRenderData;
import com.deepoove.poi.data.CellRenderData;
import com.deepoove.poi.data.MiniTableRenderData;
import com.deepoove.poi.data.style.TableStyle;
import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.apache.poi.xwpf.usermodel.XWPFParagraph;
import org.apache.poi.xwpf.usermodel.XWPFRun;
import org.apache.poi.xwpf.usermodel.XWPFTable;
import org.junit.jupiter.api.Test;
import java.util.Arrays;
import java.util.HashMap;
import java.util.Map;
import java.util.Iterator;
import java.util.Map.Entry;
import com.deepoove.poi.data.Grid;

public class HelperapplyMergeRule_XWPFTableRowgetTableCellsFikaTest {

    @Test
    public void testRenderTableToGetTableCells() throws Exception {
        XWPFDocument document = new XWPFDocument();
        XWPFParagraph paragraph = document.createParagraph();
        XWPFRun run = paragraph.createRun();

        TableRenderData tableData = createTableRenderDataWithMergeRule();

        TableRenderPolicy.Helper.renderTable(run, tableData);

        document.close();
    }

    private TableRenderData createTableRenderDataWithMergeRule() {
        RowRenderData row1 = new RowRenderData(Arrays.asList(
            new CellRenderData("A1"),
            new CellRenderData("B1"),
            new CellRenderData("C1")
        ));
        RowRenderData row2 = new RowRenderData(Arrays.asList(
            new CellRenderData("A2"),
            new CellRenderData("B2"),
            new CellRenderData("C2")
        ));
        RowRenderData row3 = new RowRenderData(Arrays.asList(
            new CellRenderData("A3"),
            new CellRenderData("B3"),
            new CellRenderData("C3")
        ));

        MiniTableRenderData miniTable = new MiniTableRenderData(
            Arrays.asList(row1, row2, row3),
            TableStyle.create()
        );

        Map<Grid, Grid> mergeMap = new HashMap<>();
        mergeMap.put(new Grid(0, 0), new Grid(1, 0));
        mergeMap.put(new Grid(0, 1), new Grid(0, 2));

        MergeCellRule mergeRule = new MergeCellRule(mergeMap);

        return new TableRenderData(miniTable, mergeRule);
    }

    private static class MergeCellRule {
        private final Map<Grid, Grid> mergeMap;

        public MergeCellRule(Map<Grid, Grid> mergeMap) {
            this.mergeMap = mergeMap;
        }

        public Iterator<Entry<Grid, Grid>> mappingIterator() {
            return mergeMap.entrySet().iterator();
        }
    }

    private static class Grid {
        private final int i;
        private final int j;

        public Grid(int i, int j) {
            this.i = i;
            this.j = j;
        }

        public int getI() { return i; }
        public int getJ() { return j; }
    }
}

