        Mockito.when(template.getXWPFDocument()).thenReturn(document);

        // Create real chart data
        ChartSingleSeriesRenderData chartData = new ChartSingleSeriesRenderData();
        SeriesRenderData seriesData = new SeriesRenderData("TestSeries", new Number[]{1.0, 2.0, 3.0});
        chartData.setSeriesData(seriesData);
        chartData.setCategories(Arrays.asList("Cat1", "Cat2", "Cat3"));

        // Create the policy instance
        SingleSeriesChartTemplateRenderPolicy policy = new SingleSeriesChartTemplateRenderPolicy();

        // Execute the entry point method
        policy.doRender(chartTemplate, chartData, template);

        // Clean up
        workbook.close();
        document.close();
    }
}

