package com.deepoove.poi.xwpf;

import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.Arrays;
import java.util.Iterator;
import java.util.List;

import org.apache.poi.xwpf.usermodel.XWPFParagraph;
import org.apache.poi.xwpf.usermodel.XWPFRun;
import org.apache.poi.xwpf.usermodel.XWPFStyles;
import org.junit.jupiter.api.Test;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTP;
import org.openxmlformats.schemas.wordprocessingml.x2006.main.CTBody;

import com.deepoove.poi.xwpf.NiceXWPFDocument;

public class XmlXWPFDocumentMergemergeStyles_POIXMLUnitsparseOnOffFikaTest {

    @Test
    public void testMergeChain() throws Exception {
        // Create source document with styles
        NiceXWPFDocument sourceDoc = new NiceXWPFDocument();
        XWPFStyles sourceStyles = sourceDoc.createStyles();

        // Create merged document with styles and a style that triggers parseOnOff
        NiceXWPFDocument mergedDoc = new NiceXWPFDocument();
        XWPFStyles mergedStyles = mergedDoc.createStyles();

        // Create a style with default attribute set to true
        org.openxmlformats.schemas.wordprocessingml.x2006.main.CTStyle ctStyle = 
            org.openxmlformats.schemas.wordprocessingml.x2006.main.CTStyle.Factory.newInstance();
        ctStyle.setStyleId("TestStyle");
        ctStyle.setDefault(org.openxmlformats.schemas.officeDocument.x2006.sharedTypes.STOnOff.Factory.newValue(true));
        ctStyle.setType(org.openxmlformats.schemas.wordprocessingml.x2006.main.STStyleType.PARAGRAPH);

        // Add the style to merged document
        mergedStyles.addStyle(new org.apache.poi.xwpf.usermodel.XWPFStyle(ctStyle));

        // Create iterator with merged document
        List<NiceXWPFDocument> docsList = Arrays.asList(mergedDoc);
        Iterator<NiceXWPFDocument> iterator = docsList.iterator();

        // Create mock run and paragraph
        XWPFRun mockRun = mock(XWPFRun.class);
        XWPFParagraph mockParagraph = mock(XWPFParagraph.class);
        when(mockRun.getParent()).thenReturn(mockParagraph);

        // Create CTP for paragraph
        CTP ctp = CTP.Factory.newInstance();
        when(mockParagraph.getCTP()).thenReturn(ctp);

        // Create CTBody for source document
        CTBody body = CTBody.Factory.newInstance();
        when(sourceDoc.getDocument()).thenReturn(new org.apache.poi.xwpf.usermodel.XWPFDocument() {
            @Override
            public CTBody getBody() {
                return body;
            }
        });

        // Create XmlXWPFDocumentMerge instance
        XmlXWPFDocumentMerge mergeInstance = new XmlXWPFDocumentMerge();

        // Execute the entry point method
        mergeInstance.merge(sourceDoc, iterator, mockRun);
    }
}

