public class XmlXWPFDocumentMergemergeFootnote_FootnoteEndnoteIdManagermethodFikaTest {

    @Test
    public void testMergeChain() throws Exception {
        // Create source document with minimal content to avoid NPEs
        XWPFDocument sourceDoc = new XWPFDocument();
        sourceDoc.createParagraph().createRun().setText("source");

        // Create merged document with minimal content
        XWPFDocument mergedDoc = new XWPFDocument();
        mergedDoc.createParagraph().createRun().setText("merged");

        // Wrap in NiceXWPFDocument
        NiceXWPFDocument source = new NiceXWPFDocument(sourceDoc);
        NiceXWPFDocument merged = new NiceXWPFDocument(mergedDoc);

        // Create iterator with the merged document
        Iterator<NiceXWPFDocument> iterator = Collections.singletonList(merged).iterator();

        // Create a paragraph and run for the merge method
        XWPFParagraph paragraph = sourceDoc.createParagraph();
        XWPFRun run = paragraph.createRun();

        // Create instance of class under test
        XmlXWPFDocumentMerge merger = new XmlXWPFDocumentMerge();

        // Execute entry point method
        merger.merge(source, iterator, run);
    }
}

