    void testMergePathToAddEndnote() throws Exception {
        // Create source document with mocked endnotes
        NiceXWPFDocument sourceDoc = mock(NiceXWPFDocument.class);
        XWPFEndnotes sourceEndnotes = mock(XWPFEndnotes.class);
        when(sourceDoc.createEndnotes()).thenReturn(sourceEndnotes);

        // Create merged document with actual endnotes
        NiceXWPFDocument mergedDoc = mock(NiceXWPFDocument.class);
        XWPFEndnote endnote = mock(XWPFEndnote.class);
        when(endnote.getId()).thenReturn(BigInteger.valueOf(1));
        when(endnote.getCTFtnEdn()).thenReturn(mock(org.openxmlformats.schemas.wordprocessingml.x2006.main.CTFtnEdn.class));

        List<XWPFEndnote> endnotesList = new ArrayList<>();
        endnotesList.add(endnote);
        when(mergedDoc.getEndnotes()).thenReturn(endnotesList);

        // Create iterator with merged document
        List<NiceXWPFDocument> docs = new ArrayList<>();
        docs.add(mergedDoc);
        Iterator<NiceXWPFDocument> iterator = docs.iterator();

        // Create run and paragraph
        XWPFRun run = mock(XWPFRun.class);
        XWPFParagraph paragraph = mock(XWPFParagraph.class);
        when(run.getParent()).thenReturn(paragraph);
        when(paragraph.getCTP()).thenReturn(mock(org.openxmlformats.schemas.wordprocessingml.x2006.main.CTP.class));

        // Mock document body and XML methods
        org.openxmlformats.schemas.wordprocessingml.x2006.main.CTBody body = 
            mock(org.openxmlformats.schemas.wordprocessingml.x2006.main.CTBody.class);
        when(sourceDoc.getDocument()).thenReturn(mock(org.apache.poi.xwpf.usermodel.XWPFDocument.class));
        when(sourceDoc.getDocument().getBody()).thenReturn(body);
        when(body.xmlText(any())).thenReturn("<w:body></w:body>");

        // Create instance and call entry point
