        PackagePart sourcePackagePart = Mockito.mock(PackagePart.class);
        PackagePart mergePackagePart = Mockito.mock(PackagePart.class);

        Mockito.when(sourceDoc.getPackagePart()).thenReturn(sourcePackagePart);
        Mockito.when(mergeDoc.getPackagePart()).thenReturn(mergePackagePart);

        XWPFParagraph paragraph = Mockito.mock(XWPFParagraph.class);
