        Iterator<PackageRelationship> relationshipIterator = Arrays.asList(relationship).iterator();

        Mockito.when(mergePackagePart.getRelationshipsByType(Mockito.anyString()))
               .thenReturn(relationshipCollection);
        Mockito.when(relationshipCollection.iterator()).thenReturn(relationshipIterator);

        Mockito.when(relationship.getTargetURI()).thenReturn(new java.net.URI("/test.docx"));
        Mockito.when(relationship.getId()).thenReturn("rId1");

