package com.deepoove.poi.xwpf;

import org.apache.poi.xwpf.usermodel.XWPFParagraph;
import org.apache.poi.xwpf.usermodel.XWPFRun;
import org.apache.poi.xwpf.usermodel.XWPFDocument;
import org.apache.poi.ooxml.POIXMLDocument;
import org.apache.poi.openxml4j.exceptions.InvalidFormatException;
import org.apache.poi.openxml4j.opc.PackageRelationship;
import org.apache.poi.openxml4j.opc.PackageRelationshipCollection;
import org.apache.poi.openxml4j.opc.PackagePart;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.util.*;

import static org.mockito.Mockito.when;

public class XmlXWPFDocumentMergemergeAttachment_POIXMLExceptionmethodFikaTest {

    @Test
    public void testMergeChainTriggersPOIXMLException() throws Exception {
        // Create source document
        NiceXWPFDocument source = new NiceXWPFDocument();

        // Create merged document that will trigger POIXMLException in mergeAttachment
        NiceXWPFDocument mergedDoc = Mockito.mock(NiceXWPFDocument.class);
        XWPFDocument mergedXWPF = Mockito.mock(XWPFDocument.class);
        when(mergedDoc.getDocument()).thenReturn(mergedXWPF);

        // Mock PackagePart for merged document
        PackagePart mergedPackagePart = Mockito.mock(PackagePart.class);
        when(mergedDoc.getPackagePart()).thenReturn(mergedPackagePart);

        // Create PackageRelationshipCollection with one relationship
        PackageRelationshipCollection relationshipCollection = Mockito.mock(PackageRelationshipCollection.class);
        when(mergedPackagePart.getRelationshipsByType(POIXMLDocument.PACK_OBJECT_REL_TYPE))
            .thenReturn(relationshipCollection);

        // Create iterator for relationships
        Iterator<PackageRelationship> relationshipIterator = createRelationshipIterator();
        when(relationshipCollection.iterator()).thenReturn(relationshipIterator);

        // Create PackagePart for embedded document
        PackagePart embeddPart = Mockito.mock(PackagePart.class);
        when(mergedPackagePart.getRelatedPart(Mockito.any(PackageRelationship.class)))
            .thenReturn(embeddPart);

        // Make InputStream throw IOException to trigger POIXMLException
        when(embeddPart.getInputStream()).thenThrow(new IOException("Test exception"));

        // Create iterator for merge documents
        List<NiceXWPFDocument> docs = Collections.singletonList(mergedDoc);
        Iterator<NiceXWPFDocument> mergeIterator = docs.iterator();

        // Create run parameter
        XWPFParagraph paragraph = Mockito.mock(XWPFParagraph.class);
        XWPFRun run = Mockito.mock(XWPFRun.class);
        when(run.getParent()).thenReturn(paragraph);

        // Create XmlXWPFDocumentMerge instance
        XmlXWPFDocumentMerge merger = new XmlXWPFDocumentMerge();

        // Execute the entry point method - this should trigger the chain ending with POIXMLException
        merger.merge(source, mergeIterator, run);
    }

    private Iterator<PackageRelationship> createRelationshipIterator() {
        PackageRelationship relationship = Mockito.mock(PackageRelationship.class);
        when(relationship.getId()).thenReturn("rId1");
        when(relationship.getTargetURI()).thenReturn(new java.net.URI("test.docx"));

        List<PackageRelationship> relationships = Collections.singletonList(relationship);
        return relationships.iterator();
    }
}

