public class XmlXWPFDocumentMergemergeNumbering_CTAbstractNumunsetNsidFikaTest {

    @Test
    public void testMergePathToUnsetNsid() throws Exception {
        // Create source document with numbering
        NiceXWPFDocument sourceDoc = new NiceXWPFDocument();
        XWPFNumbering sourceNumbering = sourceDoc.createNumbering();

        // Create merged document with numbering that has CTAbstractNum with nsid set
        NiceXWPFDocument mergedDoc = new NiceXWPFDocument();
        XWPFNumbering mergedNumbering = mergedDoc.createNumbering();

        // Create an abstract num with nsid set
        org.openxmlformats.schemas.wordprocessingml.x2006.main.CTAbstractNum ctAbstractNum = 
            org.openxmlformats.schemas.wordprocessingml.x2006.main.CTAbstractNum.Factory.newInstance();
        ctAbstractNum.setAbstractNumId(java.math.BigInteger.ONE);
        ctAbstractNum.setNsid(org.openxmlformats.schemas.wordprocessingml.x2006.main.CTLongHexNumber.Factory.newInstance());
        ctAbstractNum.getNsid().setVal(new byte[]{1, 2, 3, 4});

        // Add the abstract num to merged numbering
        mergedNumbering.addAbstractNum(new XWPFAbstractNum(ctAbstractNum));

        // Create a num referencing the abstract num
        org.openxmlformats.schemas.wordprocessingml.x2006.main.CTNum ctNum = 
            org.openxmlformats.schemas.wordprocessingml.x2006.main.CTNum.Factory.newInstance();
        ctNum.setNumId(java.math.BigInteger.valueOf(1));
        ctNum.addNewAbstractNumId().setVal(java.math.BigInteger.ONE);
        mergedNumbering.addNum(ctNum);

        // Create iterator with merged document
        List<NiceXWPFDocument> docs = new ArrayList<>();
        docs.add(mergedDoc);
        Iterator<NiceXWPFDocument> iterator = docs.iterator();

        // Create a run in a paragraph
        XWPFParagraph paragraph = new XWPFParagraph(CTP.Factory.newInstance(), sourceDoc.getDocument());
        XWPFRun run = paragraph.createRun();

        // Create XmlXWPFDocumentMerge instance
        XmlXWPFDocumentMerge merger = new XmlXWPFDocumentMerge();

        // Execute the entry point method
        merger.merge(sourceDoc, iterator, run);
    }
}

