package com.deepoove.poi.xwpf;

import org.apache.poi.xwpf.usermodel.XWPFNumbering;
import org.apache.poi.xwpf.usermodel.XWPFParagraph;
import org.apache.poi.xwpf.usermodel.XWPFRun;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.math.BigInteger;
import java.util.Collections;
import java.util.Iterator;

public class XmlXWPFDocumentMergemergeNumbering_XWPFNumberinggetAbstractNumFikaTest {

    @Test
    public void testMergePath() throws Exception {
        // Create source document with numbering
        NiceXWPFDocument source = new NiceXWPFDocument();

        // Create merged document with numbering that will trigger getAbstractNum
        byte[] docBytes = createDocumentWithNumbering();
        NiceXWPFDocument merged = new NiceXWPFDocument(new ByteArrayInputStream(docBytes));

        // Create iterator with the merged document
        Iterator<NiceXWPFDocument> mergeIterator = Collections.singletonList(merged).iterator();

        // Create a mock run that can provide a paragraph parent
        XWPFRun run = Mockito.mock(XWPFRun.class);
        XWPFParagraph paragraph = Mockito.mock(XWPFParagraph.class);
        Mockito.when(run.getParent()).thenReturn(paragraph);

        // Instantiate the class under test
        XmlXWPFDocumentMerge merger = new XmlXWPFDocumentMerge();

        // Execute the entry point method - this should trigger the full call chain
        merger.merge(source, mergeIterator, run);
    }

    private byte[] createDocumentWithNumbering() throws IOException {
        // Create a minimal document with numbering to trigger getAbstractNum call
        NiceXWPFDocument doc = new NiceXWPFDocument();

        // Create numbering in the document
        XWPFNumbering numbering = doc.createNumbering();

        // Create an abstract numbering
        org.openxmlformats.schemas.wordprocessingml.x2006.main.CTAbstractNum ctAbstractNum = 
            org.openxmlformats.schemas.wordprocessingml.x2006.main.CTAbstractNum.Factory.newInstance();
        ctAbstractNum.setAbstractNumId(BigInteger.ONE);

        // Add the abstract numbering
        numbering.addAbstractNum(new org.apache.poi.xwpf.usermodel.XWPFAbstractNum(ctAbstractNum));

        // Create a concrete numbering reference
        BigInteger numId = numbering.addNum(BigInteger.ONE);

        // Create a paragraph with numbering
        XWPFParagraph paragraph = doc.createParagraph();
        paragraph.setNumID(numId);

        // Write to byte array
        java.io.ByteArrayOutputStream baos = new java.io.ByteArrayOutputStream();
        doc.write(baos);
        doc.close();

        return baos.toByteArray();
    }
}

